def levelChoice (μ : ℕ → lp (fun _ : Point => ℝ) 1) (T : Set ℕ) (n : ℕ) : Bool :=
  if n ∈ T then (if 0 ≤ μ n (n, false) then false else true)
  else (if 0 ≤ μ n (n, false) then true else false)

